def test_generic_sidecar_validators_accept_positive_holdout_reads(tmp_path:Path):
 split='f'*64; field=tmp_path/'field'; label=tmp_path/'label'; field.mkdir(); label.mkdir(); fm={'status':'TIME_MAJOR_LAYOUT_PARITY_PASS','evaluation_role':'holdout','data_role':'holdout_report_only','split_manifest_hash':split,'validation_reads':0,'holdout_reads':2,'forward_2026_reads':0,'feedback_write':'FORBIDDEN','scheduler_write':'FORBIDDEN','archive_write':'FORBIDDEN','promotion':'FORBIDDEN','fields':['open','close'],'shards':[]}; lm={'status':'GLOBAL_SYMBOL_CONTINUITY_LABEL_SIDECARS_READY','evaluation_role':'holdout','data_role':'holdout_report_only','split_manifest_hash':split,'validation_reads':0,'holdout_reads':2,'forward_2026_reads':0}; (field/'CN_DEVELOPMENT_TIME_MAJOR_EXECUTION_LAYOUT_V2.json').write_text(json.dumps(fm),encoding='utf-8'); (label/'CN_FORWARD_LABEL_SIDECAR_MANIFEST.json').write_text(json.dumps(lm),encoding='utf-8'); replay._validate_sidecar(field,evaluation_role='holdout',split_hash=split); replay._validate_label_sidecar(label,evaluation_role='holdout',split_hash=split); fm['holdout_reads']=0; lm['holdout_reads']=0; (field/'CN_DEVELOPMENT_TIME_MAJOR_EXECUTION_LAYOUT_V2.json').write_text(json.dumps(fm),encoding='utf-8'); (label/'CN_FORWARD_LABEL_SIDECAR_MANIFEST.json').write_text(json.dumps(lm),encoding='utf-8');
 with pytest.raises(RuntimeError,match='no holdout reads'): replay._validate_sidecar(field,evaluation_role='holdout',split_hash=split)
 with pytest.raises(RuntimeError,match='no holdout reads'): replay._validate_label_sidecar(label,evaluation_role='holdout',split_hash=split)
