def test_holdout_authorization_binds_final_plan_and_report_only_boundary(tmp_path:Path):
 x=auth_builder.build(ROOT); assert x['status']=='BASE_EVENT_TIER_A_REPORT_ONLY_HOLDOUT_AUTHORIZED_NOT_RUN'; assert x['evaluation_role']=='holdout' and x['usage']=='REPORT_ONLY_CANDIDATE_TRANSFER'; assert x['resource_contract']=={'profile':'VALIDATION_DUAL_8','cpu_threads':8,'evaluator_workers':2,'candidate_count':2}; assert x['oos_authority']=='HOLDOUT_REPORT_ONLY_EVIDENCE_ONLY'; assert x['promotion_authorized'] is False and x['automatic_successor_authorized'] is False; assert x['implementation']['generic_replay_validator_sha256']; assert x['implementation']['forward_label_builder_sha256']; p=tmp_path/'auth.json';p.write_text(json.dumps(x,sort_keys=True),encoding='utf-8'); y=runtime.verify_authorization(p,repo_root=ROOT); assert y['authorization_payload_sha256']==x['authorization_payload_sha256']
def test_holdout_recovery_authorization_is_retry_only_and_incident_bound(tmp_path:Path):
 incident=json.loads((ROOT/'runtime/run_plans/cn_program_base_event_tier_a_holdout_recovery_incident_20260823.json').read_text(encoding='utf-8-sig')); x=recovery_auth_builder.build(ROOT); assert x['schema_version']==runtime.RECOVERY_AUTHORIZATION_SCHEMA; assert x['status']=='BASE_EVENT_TIER_A_REPORT_ONLY_HOLDOUT_RECOVERY_AUTHORIZED_NOT_RUN'; assert x['permitted_project_control_actions']==[ACTION_RETRY]; assert x['recovery_incident']['payload_sha256']==incident['incident_payload_sha256']; assert incident['root_cause_assessment']['status']=='REMOTE_TRACE_CONFIRMED'; assert incident['root_cause_assessment']['confirmed_error']=='thread environment is not frozen'; assert incident['fix_contract']['scope']=='PRE_EVALUATION_INFRASTRUCTURE_COMPATIBILITY_ONLY'; assert incident['recovery_preflight_assessment']['status']=='REMOTE_TRACE_CONFIRMED_ON_RETRY1'; assert incident['retry1_failure_assessment']['confirmed_error']=='holdout field sidecar drift: holdout_reads'; assert x['recovery_contract']['recovery_kind']=='INFRASTRUCTURE_PRE_EVALUATION_RETRY_FAILURE'; assert x['recovery_contract']['failed_target_run_id']=='cn_program_base_event_tier_a_report_only_holdout_retry1_20260823_5a04996'; assert x['recovery_contract']['recovery_scope']=='PRE_EVALUATION_INFRASTRUCTURE_COMPATIBILITY_ONLY'; assert x['recovery_contract']['failed_admission_file_sha256']=='937a868f164b6cee132b677310cac1347d420f07571e9146a46e3c5ef7674f86'; assert x['recovery_contract']['fresh_output_root_required'] is True; assert x['implementation']['generic_replay_validator_sha256']; assert x['implementation']['forward_label_builder_sha256']; p=tmp_path/'recovery_auth.json';p.write_text(json.dumps(x,sort_keys=True),encoding='utf-8'); y=runtime.verify_authorization(p,repo_root=ROOT); assert y['authorization_payload_sha256']==x['authorization_payload_sha256']
